#include <stdio.h>
#include <fcntl.h>
#include <unistd.h>
#include <dftracer/dftracer.h>

static int do_read(const char *path) {
  DFTRACER_C_FUNCTION_START();
  DFTRACER_C_FUNCTION_UPDATE_STR("comp", "io");
  DFTRACER_C_FUNCTION_UPDATE_STR("fname", path);
  int fd = open(path, O_RDONLY);
  if (fd < 0) {
    DFTRACER_C_FUNCTION_END();
    return -1;
  }
  close(fd);
  DFTRACER_C_FUNCTION_END();
  return 0;
}

int main(int argc, char **argv) {
  DFTRACER_C_INIT(NULL, NULL, NULL);
  DFTRACER_C_FUNCTION_START();
  DFTRACER_C_FUNCTION_UPDATE_STR("comp", "io");
  // dftracer app-parameter metadata
  DFTRACER_C_METADATA(meta_n, "n", "1");
  int r = do_read(argc > 1 ? argv[1] : "x");
  DFTRACER_C_FINI();
  DFTRACER_C_FUNCTION_END();
  return r;
}

