#include <cstdio>
#include <dftracer/dftracer.h>
namespace app {
int write_file(const char *path) {
  DFTRACER_CPP_FUNCTION();
  DFTRACER_CPP_FUNCTION_UPDATE("comp", "io");
  DFTRACER_CPP_FUNCTION_UPDATE("path", path);
  FILE *f = fopen(path, "w");
  if (!f) return -1;
  fclose(f);
  return 0;
}
}
int main(int argc, char **argv) {
  DFTRACER_CPP_INIT(nullptr, nullptr, nullptr);
  DFTRACER_CPP_REGION_START(main);
  int r = app::write_file(argc > 1 ? argv[1] : "x");
  DFTRACER_CPP_REGION_END(main);
  DFTRACER_CPP_FINI();
  return r;
}

